"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def countVowels(paragraph):
    vowelCount = {}
    vowelCount['a'] = 0
    vowelCount['e'] = 0
    vowelCount['i'] = 0
    vowelCount['o'] = 0
    vowelCount['u'] = 0
    for __reserved_keyword__char in paragraph:
        lowerChar = str(__reserved_keyword__char).lower()
        if (lowerChar in vowelCount):
            vowelCount[lowerChar] = (vowelCount[lowerChar] + 1)
    return vowelCount
print(countVowels("Hello World"))